import json, urllib.request, sys
ids = [l.strip() for l in open('/app/pdb_ids.txt') if l.strip()]
for i in ids:
    try:
        d = json.load(urllib.request.urlopen('https://data.rcsb.org/rest/v1/core/entry/'+i, timeout=30))
    except Exception as e:
        print(i, 'ERR', e); continue
    print('===', i, '===')
    print('TITLE:', d.get('struct',{}).get('title',''))
    for ent in d.get('rcsb_entry_info', []):
        pass
    # entities
    try:
        ents = json.load(urllib.request.urlopen('https://data.rcsb.org/rest/v1/core/entry/'+i+'/entities', timeout=30))
        for e in ents.get('data', []):
            nm = e.get('rcsb_macromolecular_names_combined',{}).get('long','')
            tp = e.get('rcsb_macromolecular_type',{})
            print('  ENT', e.get('rcsb_entity_id'), tp, '|', nm)
    except Exception as e:
        print('  ent err', e)
